import 'package:flutter/material.dart';import 'package:flutter/services.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../theme/personal_theme.dart';import '../../theme/theme_center_catalog_generated.dart';import '../../theme/theme_library_provider.dart';import '../../theme/theme_settings_provider.dart';
String themeCenterText(BuildContext context,String en,String fr,String es) => Localizations.localeOf(context).languageCode=='fr'?fr:Localizations.localeOf(context).languageCode=='es'?es:en;
class ThemeCenterPanel extends ConsumerWidget {
 const ThemeCenterPanel({super.key});
 Future<void> _run(BuildContext context,Future<void> Function() action) async {try{await action();}catch(_){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(themeCenterText(context,'Unable to save or apply. Use a unique name and valid settings.','Impossible d’enregistrer ou d’appliquer. Utilisez un nom unique et des paramètres valides.','No se pudo guardar o aplicar. Use un nombre único y parámetros válidos.'))));}}
 Future<String?> _name(BuildContext context,String initial) async {final controller=TextEditingController(text:initial);final result=await showDialog<String>(context:context,builder:(c)=>AlertDialog(title:Text(themeCenterText(context,'Theme name','Nom du thème','Nombre del tema')),content:TextField(controller:controller,maxLength:60,autofocus:true),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:Text(themeCenterText(context,'Cancel','Annuler','Cancelar'))),FilledButton(onPressed:()=>Navigator.pop(c,controller.text),child:Text(themeCenterText(context,'Save','Enregistrer','Guardar')))]));controller.dispose();return result;}
 Future<PersonalTheme?> _edit(BuildContext context,PersonalTheme initial) async {
  final controllers={for(final key in themeCenterColorKeys)key:TextEditingController(text:initial.colors[key]??'')};var font=initial.fontFamily,scale=initial.fontScale,radius=initial.radius;
  final result=await showDialog<PersonalTheme>(context:context,builder:(c)=>StatefulBuilder(builder:(c,setState)=>AlertDialog(title:Text(themeCenterText(context,'Edit theme','Modifier le thème','Editar tema')),content:SizedBox(width:420,child:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<String>(initialValue:font,decoration:InputDecoration(labelText:themeCenterText(context,'Font','Police','Fuente')),items:['system','serif','monospace'].map((f)=>DropdownMenuItem(value:f,child:Text(f))).toList(),onChanged:(v)=>setState(()=>font=v!)),Text('${themeCenterText(context,'Text scale','Échelle du texte','Escala del texto')}: ${scale.toStringAsFixed(3)}'),Slider(value:scale,min:.875,max:1.5,divisions:5,onChanged:(v)=>setState(()=>scale=v)),Text('${themeCenterText(context,'Corner radius','Rayon des coins','Radio de esquinas')}: $radius'),Slider(value:radius.toDouble(),min:0,max:24,divisions:24,onChanged:(v)=>setState(()=>radius=v.round())),...themeCenterColorKeys.map((key)=>TextField(controller:controllers[key],maxLength:7,decoration:InputDecoration(labelText:key,hintText:'#RRGGBB'))),Text(themeCenterText(context,'Leave colors empty to inherit the palette. Text contrast adjusts automatically.','Laissez les couleurs vides pour hériter de la palette. Le contraste est ajusté.','Deje los colores vacíos para heredar la paleta. Se ajusta el contraste.'))]))),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:Text(themeCenterText(context,'Cancel','Annuler','Cancelar'))),FilledButton(onPressed:(){try{final theme=PersonalTheme(name:initial.name,preset:initial.preset,fontFamily:font,fontScale:scale,radius:radius,colors:{for(final entry in controllers.entries)if(entry.value.text.trim().isNotEmpty)entry.key:entry.value.text.trim()}).validated();Navigator.pop(c,theme);}catch(_){ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Use #RRGGBB colors.')));}},child:Text(themeCenterText(context,'Apply','Appliquer','Aplicar')))])));
  for(final c in controllers.values)c.dispose();return result;
 }
 @override Widget build(BuildContext context,WidgetRef ref) {
  final current=ref.watch(themeSettingsProvider).theme,items=ref.watch(themeLibraryProvider);final settings=ref.read(themeSettingsProvider.notifier),library=ref.read(themeLibraryProvider.notifier);
  return Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text(themeCenterText(context,'THEME CENTER','CENTRE DES THÈMES','CENTRO DE TEMAS'),style:Theme.of(context).textTheme.titleMedium),Text(themeCenterText(context,'Personal themes are saved for this account and role on this device.','Les thèmes sont enregistrés pour ce compte et rôle sur cet appareil.','Los temas se guardan para esta cuenta y rol en este dispositivo.')),Wrap(spacing:8,children:[OutlinedButton(onPressed:()=>_run(context,()async{final edited=await _edit(context,current);if(edited!=null)await settings.applyPersonalTheme(edited);}),child:Text(themeCenterText(context,'Edit current','Modifier','Editar'))),FilledButton(onPressed:()=>_run(context,()async{final name=await _name(context,current.name);if(name!=null)await library.save(current.named(name));}),child:Text(themeCenterText(context,'Save as new','Enregistrer nouveau','Guardar nuevo'))),OutlinedButton(onPressed:()=>_run(context,()async{await Clipboard.setData(ClipboardData(text:current.exportJson()));if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(themeCenterText(context,'Theme JSON copied.','Thème JSON copié.','Tema JSON copiado.'))));}),child:Text(themeCenterText(context,'Export','Exporter','Exportar'))),OutlinedButton(onPressed:()=>_run(context,()async{final controller=TextEditingController();final value=await showDialog<String>(context:context,builder:(c)=>AlertDialog(title:Text(themeCenterText(context,'Import theme JSON','Importer le thème JSON','Importar tema JSON')),content:TextField(controller:controller,maxLength:16384,maxLines:8),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:Text(themeCenterText(context,'Cancel','Annuler','Cancelar'))),FilledButton(onPressed:()=>Navigator.pop(c,controller.text),child:Text(themeCenterText(context,'Import','Importer','Importar')))]));controller.dispose();if(value!=null)await settings.applyPersonalTheme(PersonalTheme.importJson(value));}),child:Text(themeCenterText(context,'Import','Importer','Importar')))]),...items.map((item)=>ListTile(title:Text(item.theme.name),subtitle:Text(item.theme.preset),onTap:()=>_run(context,()=>settings.applyPersonalTheme(item.theme)),trailing:PopupMenuButton<String>(onSelected:(action)=>_run(context,()async{if(action=='delete'){await library.remove(item.id);return;}if(action=='update'){await library.save(current.named(item.theme.name),id:item.id);return;}final name=await _name(context,action=='duplicate'?'${item.theme.name} copy':item.theme.name);if(name==null)return;if(action=='rename'){await library.rename(item.id,name);if(current.name==item.theme.name)await settings.applyPersonalTheme(current.named(name));}else await library.duplicate(item.id,name);}),itemBuilder:(c)=>[PopupMenuItem(value:'update',child:Text(themeCenterText(context,'Update from current','Mettre à jour','Actualizar'))),PopupMenuItem(value:'rename',child:Text(themeCenterText(context,'Rename','Renommer','Renombrar'))),PopupMenuItem(value:'duplicate',child:Text(themeCenterText(context,'Duplicate','Dupliquer','Duplicar'))),PopupMenuItem(value:'delete',child:Text(themeCenterText(context,'Delete','Supprimer','Eliminar')))]))),const SizedBox(height:24)]);
 }
}
